'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { Plus, X, BookOpen } from 'lucide-react';

export default function ProgramsPage() {
    const [programs, setPrograms] = useState<any[]>([]);
    const [departments, setDepartments] = useState<any[]>([]);
    const [showForm, setShowForm] = useState(false);
    const [form, setForm] = useState({ name: '', code: '', department_id: '', duration_years: 4 });

    const load = async () => {
        try {
            const [pRes, dRes] = await Promise.all([
                api.get<any[]>('/api/admin/programs'),
                api.get<any[]>('/api/admin/departments'),
            ]);
            if (pRes.success) setPrograms(pRes.data);
            if (dRes.success) setDepartments(dRes.data);
        } catch (e) { }
    };

    useEffect(() => { load(); }, []);

    const handleCreate = async () => {
        try {
            await api.post('/api/admin/programs', form);
            setShowForm(false);
            setForm({ name: '', code: '', department_id: '', duration_years: 4 });
            load();
        } catch (e) { }
    };

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
                <div>
                    <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins' }}>Programs</h1>
                    <p style={{ fontSize: 14, color: '#5a6a72' }}>Manage degree programs</p>
                </div>
                <button className="btn-primary" onClick={() => setShowForm(true)}><Plus size={16} /> Add Program</button>
            </div>

            {showForm && (
                <div className="card" style={{ marginBottom: 24, padding: 28 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 16 }}>
                        <h3 style={{ fontSize: 16, fontWeight: 700 }}>New Program</h3>
                        <button onClick={() => setShowForm(false)} style={{ background: 'none', border: 'none', cursor: 'pointer' }}><X size={18} color="#8a9aa2" /></button>
                    </div>
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
                        <div className="form-group"><label>Name</label><input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="B.Tech Computer Science" /></div>
                        <div className="form-group"><label>Code</label><input value={form.code} onChange={(e) => setForm({ ...form, code: e.target.value })} placeholder="BTCS" /></div>
                        <div className="form-group"><label>Department</label>
                            <select value={form.department_id} onChange={(e) => setForm({ ...form, department_id: e.target.value })}>
                                <option value="">Select department</option>
                                {departments.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
                            </select>
                        </div>
                        <div className="form-group"><label>Duration (Years)</label><input type="number" value={form.duration_years} onChange={(e) => setForm({ ...form, duration_years: parseInt(e.target.value) })} /></div>
                    </div>
                    <button className="btn-primary" onClick={handleCreate}>Create</button>
                </div>
            )}

            <div className="table-container">
                <table>
                    <thead><tr><th>Name</th><th>Code</th><th>Duration</th></tr></thead>
                    <tbody>
                        {programs.length === 0 ? (
                            <tr><td colSpan={3} style={{ textAlign: 'center', padding: 32, color: '#8a9aa2' }}>No programs yet</td></tr>
                        ) : programs.map((p) => (
                            <tr key={p.id}>
                                <td style={{ fontWeight: 600 }}>{p.name}</td>
                                <td><code style={{ fontSize: 13, background: '#f3f4f6', padding: '2px 8px', borderRadius: 4 }}>{p.code}</code></td>
                                <td>{p.duration_years} years</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}
